// SweetAlert2 Lite - Lightweight Zero-Dependency Alert Modal for JARVIS Kids OS
(function(window) {
  'use strict';
  var Swal = {
    fire: function(opts) {
      if (typeof opts === 'string') {
        opts = { title: opts };
      }
      opts = opts || {};
      var title = opts.title || '';
      var text = opts.text || opts.html || '';
      var icon = opts.icon || 'info'; // success, error, warning, info
      var confirmText = opts.confirmButtonText || 'Entendido! 🚀';
      var timer = opts.timer || null;

      var iconEmojis = {
        success: '🎉',
        error: '⚠️',
        warning: '⚡',
        info: '🤖',
        question: '❓'
      };

      // Remove existing modal if any
      var existing = document.getElementById('swal-overlay-jarvis');
      if (existing) existing.remove();

      var overlay = document.createElement('div');
      overlay.id = 'swal-overlay-jarvis';
      overlay.style.position = 'fixed';
      overlay.style.top = '0';
      overlay.style.left = '0';
      overlay.style.width = '100vw';
      overlay.style.height = '100vh';
      overlay.style.background = 'rgba(3, 7, 18, 0.85)';
      overlay.style.backdropFilter = 'blur(6px)';
      overlay.style.display = 'flex';
      overlay.style.alignItems = 'center';
      overlay.style.justifyContent = 'center';
      overlay.style.zIndex = '999999';

      var box = document.createElement('div');
      box.className = 'animate__animated animate__zoomIn';
      box.style.background = '#091326';
      box.style.border = '2.5px solid #00f0ff';
      box.style.borderRadius = '24px';
      box.style.padding = '24px 28px';
      box.style.maxWidth = '420px';
      box.style.width = '88%';
      box.style.textAlign = 'center';
      box.style.boxShadow = '0 0 35px rgba(0, 240, 255, 0.4)';
      box.style.color = '#ffffff';

      var emoji = iconEmojis[icon] || '🤖';
      box.innerHTML =
        '<div style="font-size:3.2rem;margin-bottom:10px;">' + emoji + '</div>' +
        '<h3 style="font-size:1.35rem;font-weight:900;color:#00f0ff;margin-bottom:8px;">' + title + '</h3>' +
        '<div style="font-size:1rem;color:#cbd5e1;line-height:1.4;margin-bottom:20px;">' + text + '</div>' +
        '<button id="swal-btn-confirm" style="background:linear-gradient(135deg,#0284c7,#00f0ff);color:#030712;border:none;padding:12px 28px;border-radius:14px;font-size:1.05rem;font-weight:900;cursor:pointer;box-shadow:0 4px 15px rgba(0,240,255,0.4);">' +
        confirmText +
        '</button>';

      overlay.appendChild(box);
      document.body.appendChild(overlay);

      return new Promise(function(resolve) {
        function close(val) {
          overlay.remove();
          resolve({ isConfirmed: val });
        }

        var btn = document.getElementById('swal-btn-confirm');
        if (btn) {
          btn.onclick = function() { close(true); };
        }
        overlay.onclick = function(e) {
          if (e.target === overlay) close(false);
        };

        if (timer) {
          setTimeout(function() {
            close(true);
          }, timer);
        }
      });
    }
  };

  window.Swal = Swal;
})(window);
